def simplify_roles(apps, schema_editor):
    """L'administrateur ne fait plus que regarder les gains ; les développeurs gèrent tout."""
    User = apps.get_model("core", "User")
    Invitation = apps.get_model("core", "Invitation")
    # Plus de sous-administrateurs : comptes suspendus, invitations annulées.
    User.objects.filter(kind="admin", is_principal=False).update(is_active=False, roles=[])
    User.objects.filter(kind="admin", is_principal=True).update(roles=[])
    Invitation.objects.filter(kind="sub_admin").update(revoked=True)
    rename = {"dev_documents": "documents"}
    valid = {"events", "links", "registrations", "documents", "purge", "accounts", "audit", "settings"}
    for u in User.objects.filter(kind="developer", is_principal=False):
        u.roles = sorted({rename.get(r, r) for r in u.roles} & valid)
        u.save(update_fields=["roles"])


